using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncLifetime
{
    private readonly HttpListener listener = new();
    private readonly string baseUrl;
    private HttpClient client = null!;

    private int status = 200;
    private string responseBody = "{}";
    private string? method, path, contentType, requestBody;

    public HttpPaymentGatewayTests()
    {
        using var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        baseUrl = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(baseUrl);
    }

    public Task InitializeAsync()
    {
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
        _ = Task.Run(async () =>
        {
            while (listener.IsListening)
            {
                HttpListenerContext ctx;
                try { ctx = await listener.GetContextAsync(); } catch { return; }
                method = ctx.Request.HttpMethod;
                path = ctx.Request.Url!.AbsolutePath;
                contentType = ctx.Request.ContentType;
                using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8))
                    requestBody = await reader.ReadToEndAsync();
                var bytes = Encoding.UTF8.GetBytes(responseBody);
                ctx.Response.StatusCode = status;
                ctx.Response.ContentType = "application/json";
                await ctx.Response.OutputStream.WriteAsync(bytes);
                ctx.Response.Close();
            }
        });
        return Task.CompletedTask;
    }

    public Task DisposeAsync()
    {
        client.Dispose();
        listener.Close();
        return Task.CompletedTask;
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_the_provider_field_names()
    {
        responseBody = """{"status":"approved"}""";

        await Authorize();

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(requestBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        responseBody = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        responseBody = """{"id":"auth_1","status":"approved","risk":{"score":3}}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_payment_required_refusal_is_read_as_declined()
    {
        status = 402;
        responseBody = """{"error":"card_refused"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_are_raised_not_mistaken_for_a_decline(int code)
    {
        status = code;
        responseBody = """{"error":"nope"}""";
        var ex = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)code, ex.StatusCode);
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_treated_as_approved()
    {
        responseBody = """{"status":"pending"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        responseBody = """{"result":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_malformed_answer_is_raised()
    {
        responseBody = "<html>gateway error</html>";
        await Assert.ThrowsAsync<JsonException>(Authorize);
    }
}
